import{_ as e,o as d,c as a,al as r}from"./chunks/framework.BawR2jEz.js";const x=JSON.parse('{"title":"Функции Twig exDoc","description":"Справочник глобальных Twig-функций объекта ex — что делает каждая функция и что возвращает.","frontmatter":{"title":"Функции Twig exDoc","description":"Справочник глобальных Twig-функций объекта ex — что делает каждая функция и что возвращает."},"headers":[],"relativePath":"editor/template/functions/index.md","filePath":"editor/template/functions/index.md"}'),o={name:"editor/template/functions/index.md"};function c(h,t,i,l,n,s){return d(),a("div",null,[...t[0]||(t[0]=[r('<div><h1 id="функции-twig-exdoc" tabindex="-1">Функции Twig exDoc <a class="header-anchor" href="#функции-twig-exdoc" aria-label="Permalink to &quot;Функции Twig exDoc&quot;">​</a></h1><p>Глобальные функции объекта <code>ex</code>, доступные в любом Twig-шаблоне exDoc. У каждой функции своя страница с параметрами, возвращаемым значением и примерами.</p><h2 id="блоки-поля-и-компоненты" tabindex="-1">Блоки, поля и компоненты <a class="header-anchor" href="#блоки-поля-и-компоненты" aria-label="Permalink to &quot;Блоки, поля и компоненты&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Функция</th><th>Возвращает</th><th>Описание</th></tr></thead><tbody><tr><td><a href="./block.html">ex.block()</a></td><td><code>string</code></td><td>HTML визуального блока по ID или хэштегу</td></tr><tr><td><a href="./global_fld.html">ex.global_fld()</a></td><td><code>string</code></td><td>HTML глобального поля</td></tr><tr><td><a href="./component.html">ex.component()</a></td><td><code>string</code></td><td>HTML глобального компонента</td></tr><tr><td><a href="./component_uniqid.html">ex.component_uniqid()</a></td><td><code>string</code></td><td>Собственный идентификатор компонента для <code>{% embed %}</code></td></tr><tr><td><a href="./component_lang.html">ex.component_lang()</a></td><td><code>array</code></td><td>Языковой словарь компонента для <code>{% embed %}</code></td></tr><tr><td><a href="./rubric_thumb.html">ex.rubric_thumb()</a></td><td><code>string</code></td><td>HTML превью рубрики для элемента контента</td></tr></tbody></table><h2 id="изображения" tabindex="-1">Изображения <a class="header-anchor" href="#изображения" aria-label="Permalink to &quot;Изображения&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Функция</th><th>Возвращает</th><th>Описание</th></tr></thead><tbody><tr><td><a href="./image_resize.html">ex.image_resize()</a></td><td><code>array|string|null</code></td><td>Уменьшенная копия и WebP-версия изображения</td></tr><tr><td><a href="./get_attachment_image.html">ex.get_attachment_image()</a></td><td><code>array|null</code></td><td>Ссылки, размеры, mime-тип, <code>srcset</code> и <code>sizes</code></td></tr><tr><td><a href="./calculate_image_srcset.html">ex.calculate_image_srcset()</a></td><td><code>array</code></td><td>Готовые строки <code>srcset</code></td></tr><tr><td><a href="./calculate_image_sizes.html">ex.calculate_image_sizes()</a></td><td><code>string</code></td><td>Значение атрибута <code>sizes</code></td></tr></tbody></table><h2 id="сущности" tabindex="-1">Сущности <a class="header-anchor" href="#сущности" aria-label="Permalink to &quot;Сущности&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Функция</th><th>Возвращает</th><th>Описание</th></tr></thead><tbody><tr><td><a href="./get.html">ex.get()</a></td><td><code>object|array</code></td><td>Объект сущности по типу и ID</td></tr><tr><td><a href="./get_list.html">ex.get_list()</a></td><td><code>array</code></td><td>Список товаров или документов с пагинацией</td></tr></tbody></table><h2 id="страница-и-посетитель" tabindex="-1">Страница и посетитель <a class="header-anchor" href="#страница-и-посетитель" aria-label="Permalink to &quot;Страница и посетитель&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Функция</th><th>Возвращает</th><th>Описание</th></tr></thead><tbody><tr><td><a href="./page_info.html">ex.page_info()</a></td><td><code>string</code></td><td>Базовый URL, текущий маршрут или тип устройства</td></tr><tr><td><a href="./getCurrentFullUrl.html">ex.getCurrentFullUrl()</a></td><td><code>string</code></td><td>Полный адрес текущей страницы</td></tr></tbody></table><p>Заголовок страницы, хлебные крошки и данные покупателя лежат в объектах OpenCart — <a href="./../oc/document.html"><code>oc.document()</code></a> и <a href="./../oc/customer.html"><code>oc.customer()</code></a>.</p><h2 id="ссылки-и-подключение-ресурсов" tabindex="-1">Ссылки и подключение ресурсов <a class="header-anchor" href="#ссылки-и-подключение-ресурсов" aria-label="Permalink to &quot;Ссылки и подключение ресурсов&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Функция</th><th>Возвращает</th><th>Описание</th></tr></thead><tbody><tr><td><a href="./include_route.html">ex.include_route()</a></td><td><code>mixed</code></td><td>Результат работы контроллера OpenCart</td></tr><tr><td><a href="./ico.html">ex.ico()</a></td><td><code>string</code></td><td>Разметка SVG-иконки из спрайта</td></tr><tr><td><a href="./getExdocStyleLink.html">ex.getExdocStyleLink()</a></td><td><code>string</code></td><td>URL скомпилированного CSS-файла exDoc</td></tr><tr><td><a href="./getExdocJavascriptLink.html">ex.getExdocJavascriptLink()</a></td><td><code>string</code></td><td>URL скомпилированного JS-файла exDoc</td></tr></tbody></table><p>Ссылки на страницы магазина собирает сборщик OpenCart — <a href="./../oc/url.html"><code>oc.url()</code></a>.</p><h2 id="запрос-и-служебные" tabindex="-1">Запрос и служебные <a class="header-anchor" href="#запрос-и-служебные" aria-label="Permalink to &quot;Запрос и служебные&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Функция</th><th>Возвращает</th><th>Описание</th></tr></thead><tbody><tr><td><a href="./_request.html">ex._request()</a></td><td><code>mixed</code></td><td>Параметр GET или POST</td></tr><tr><td><a href="./_cookie.html">ex._cookie()</a></td><td><code>string|array</code></td><td>Значение cookie, JSON разбирается автоматически</td></tr><tr><td><a href="./_setcookie.html">ex._setcookie()</a></td><td>—</td><td>Установка cookie</td></tr><tr><td><a href="./_array_column.html">ex._array_column()</a></td><td><code>array</code></td><td>Колонка значений из массива</td></tr><tr><td><a href="./translite.html">ex.translite()</a></td><td><code>string</code></td><td>Транслитерация кириллицы в латиницу</td></tr></tbody></table><h2 id="своих-функции-не-хватает" tabindex="-1">Своих функций не хватает? <a class="header-anchor" href="#своих-функции-не-хватает" aria-label="Permalink to &quot;Своих функций не хватает?&quot;">​</a></h2><p>Собственные функции добавляются в отдельный файл модуля, который <strong>не перезаписывается при обновлении</strong> exDoc — там же заводятся и свои фильтры. Как это включить и что можно внутри — <a href="./../custom.html">Свои функции и фильтры</a>.</p><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./../custom.html">Свои функции и фильтры</a> — собственные <code>my_func()</code> и <code>|my_filter</code>, переживающие обновление</li><li><a href="./../oc/">Объект oc</a> — доступ к настройкам, документу, запросу, покупателю и моделям OpenCart</li><li><a href="./../methods/">Контекстные методы</a> — <code>fld()</code>, <code>fld_list()</code>, <code>component()</code>, <code>preset_fld()</code> внутри шаблонов сущностей</li><li><a href="./../filters/">Фильтры Twig exDoc</a> — обработка текста, чисел, дат и массивов</li><li><a href="./../twig-basics.html">Основы Twig</a> — стандартный синтаксис Twig</li><li><a href="./../tips.html">Полезные приёмы</a> — паттерны и трюки для шаблонов</li><li><a href="./../../../rubrics/exdoc-document/context.html">Объекты в шаблонах рубрик</a> — что доступно у документа, категории, товара</li></ul></div>',1)])])}const f=e(o,[["render",c]]);export{x as __pageData,f as default};
